#!/usr/bin/env python3
"""Synthetic, read-only HTTP measurements after seeding an isolated local database."""
import concurrent.futures, json, math, os, pathlib, platform, subprocess, time, urllib.request, urllib.parse
if os.environ.get('CONFIRM_ISOLATED_DATABASE')!='1':raise SystemExit('Requires an isolated database and CONFIRM_ISOLATED_DATABASE=1')
base=os.environ.get('BENCHMARK_BASE_URL','http://127.0.0.1:18080/api/v1/').rstrip('/')+'/'
if urllib.parse.urlparse(base).hostname not in ('localhost','127.0.0.1','::1'):raise SystemExit('Only loopback targets are accepted')
container=os.environ.get('MYSQL_CONTAINER')
def sql(query):
    if container:cmd=['docker','exec','-i','-e','MYSQL_PWD',container,'mysql','-uroot']
    else:
        cmd=[str(pathlib.Path(os.environ['MYSQL_BIN_DIR'])/'mysql') if os.environ.get('MYSQL_BIN_DIR') else 'mysql','-u'+os.environ.get('MYSQL_USER','root')]
        cmd+=['--socket='+os.environ['MYSQL_SOCKET']] if os.environ.get('MYSQL_SOCKET') else ['-h127.0.0.1','-P'+os.environ.get('MYSQL_PORT','3306')]
    return subprocess.run(cmd+['--batch','--skip-column-names','zhixuewuli'],input=query,text=True,check=True,capture_output=True).stdout.strip()
def http(path,token=None,data=None):
    headers={'Content-Type':'application/json','X-Session-Id':'20261018120000_benchmark0000000'}
    if token:headers['Authorization']='Bearer '+token
    req=urllib.request.Request(base+path,data=None if data is None else json.dumps(data).encode(),headers=headers)
    with urllib.request.urlopen(req,timeout=30) as response:
        body=response.read();return response.status,json.loads(body),len(body)
_,login,_=http('auth/login',data={'username':os.environ.get('E2E_TEACHER_USERNAME','e2e_teacher'),'password':os.environ.get('E2E_TEACHER_PASSWORD','E2e-teacher-fixture-2026')})
token=login['data']['token'];teacher_id=login['data']['userId']
# Names and IDs are reserved only in the disposable fixture DB. No real user values are exported.
event=880000;students=100;questions=50;rows=students*questions
sql(f"DELETE FROM student_reports WHERE event_id={event};DELETE FROM conversation_history WHERE event_id={event};DELETE FROM answer_records WHERE event_id={event};DELETE FROM teacher_event_questions WHERE event_id={event};DELETE FROM task_recipients WHERE event_id={event};DELETE FROM teacher_events WHERE id={event};DELETE FROM questions WHERE id BETWEEN 880001 AND 880050;DELETE FROM users WHERE id BETWEEN 881001 AND 881100;")
users=','.join(f"({881000+i},'bench_student_{i}','not-a-login-hash','Fixture {i}','STUDENT',true)" for i in range(1,students+1))
qs=','.join(f"({880000+i},'Synthetic force problem {i}','bench-hash-{i}','{{\"A\":\"3m/s²\",\"B\":\"12m/s²\"}}','A',1)" for i in range(1,questions+1))
sql(f"INSERT INTO users(id,username,password_hash,real_name,user_type,active) VALUES {users};INSERT INTO questions(id,content,content_hash,options,correct_option,difficulty) VALUES {qs};INSERT INTO teacher_events(id,teacher_id,teacher_name,event_title,event_timestamp,status) VALUES({event},{teacher_id},'Fixture','Synthetic benchmark',UTC_TIMESTAMP(),'CLOSED');")
sql(f"INSERT INTO task_recipients(event_id,user_id,source) SELECT {event},id,'PUBLISHED' FROM users WHERE id BETWEEN 881001 AND 881100;")
sql(f"INSERT INTO teacher_event_questions(event_id,question_id,bank_question_id,position_number,snapshot_json,snapshot_origin) SELECT {event},id,id,id-880001,JSON_OBJECT('id',id,'content',content,'options',CAST(options AS CHAR),'correctOption',correct_option,'difficulty',difficulty),'PUBLISHED' FROM questions WHERE id BETWEEN 880001 AND 880050;")
# Batched fixture inserts preserve the same one original assignment per student/task/question contract.
for start in range(0,rows,500):
    values=[]
    for n in range(start,min(start+500,rows)):
        u=881001+n//questions;q=880001+n%questions;correct=n%4!=0
        values.append(f"('bench-{n}',{u},{q},{event},'bench-session-{u}','{'A' if correct else 'B'}',{str(correct).lower()},false,UTC_TIMESTAMP(),JSON_OBJECT('content','fixture','imageBase64',REPEAT('x',1024)))")
    sql("INSERT INTO answer_records(id,user_id,question_id,event_id,session_id,selected_option,correct,practice,answered_at,question_snapshot) VALUES "+','.join(values))
sql(f"INSERT INTO conversation_history(user_id,event_id,session_id,question,answer,sequence_number,token_count,conversation_type,is_active) VALUES(881001,{event},'benchmark-restore','Synthetic restore input','Synthetic restore output',1,10,'REAL_TIME_QA',true);INSERT INTO student_reports(user_id,event_id,real_name,session_id,report_content,evidence_json) VALUES(881001,{event},'Synthetic fixture','benchmark-restore','Synthetic restore report; not generated by AI','{{\"fixture\":true}}');")
sql('ANALYZE TABLE answer_records')
paths={'page':f'answer-records/teacher/page?page=1&size=20&eventId={event}','summary':f'answer-records/teacher/summary?eventId={event}'}
for path in paths.values():
    for _ in range(5):assert http(path,token)[0]==200
# A fast response with an empty/mis-scoped aggregate must not count as a successful benchmark.
_,summary,_=http(paths['summary'],token)
expected={'totalAttempts':rows,'assignmentAnswers':rows,'eligibleStudents':students,
          'participatingStudents':students,'completedStudents':students,'questionCount':questions}
for key,value in expected.items():assert summary['data'][key]==value,(key,summary['data'][key],value)
count=int(os.environ.get('BENCHMARK_REQUESTS','400'));workers=int(os.environ.get('BENCHMARK_CONCURRENCY','8'))
if not 2<=count<=100000 or not 1<=workers<=64:raise SystemExit('requests must be 2..100000 and concurrency 1..64')
def run(item):
    name,path=item;start=time.perf_counter()
    try:
        status,body,size=http(path,token);ok=status==200 and body.get('code')==200
        return name,(time.perf_counter()-start)*1000,ok,size
    except Exception:return name,(time.perf_counter()-start)*1000,False,0
started=time.perf_counter()
with concurrent.futures.ThreadPoolExecutor(max_workers=workers) as pool:results=list(pool.map(run,[list(paths.items())[i%2] for i in range(count)]))
elapsed=time.perf_counter()-started
output={'scope':'synthetic local MySQL HTTP reads; AI disabled; not production capacity','databaseVersion':sql('SELECT VERSION()'),'platform':platform.system()+' '+platform.machine(),'cpu':platform.processor(),'logicalCores':os.cpu_count(),'javaVersion':os.environ.get('BENCHMARK_JAVA_VERSION','21'),'dataset':{'students':students,'questions':questions,'answers':rows,'snapshotImageBytesPerAnswer':1024},'requests':count,'concurrency':workers,'durationSeconds':round(elapsed,3),'successfulRequests':sum(r[2] for r in results),'requestsPerSecond':round(count/elapsed,2),'endpoints':{}}
for name in paths:
    subset=[r for r in results if r[0]==name];latency=sorted(r[1] for r in subset)
    percentile=lambda p:round(latency[max(0,math.ceil(p*len(latency))-1)],2)
    output['endpoints'][name]={'samples':len(subset),'p50Ms':percentile(.5),'p95Ms':percentile(.95),'p99Ms':percentile(.99),'meanResponseBytes':round(sum(r[3] for r in subset)/len(subset))}
print(json.dumps(output,ensure_ascii=False,indent=2))
if output['successfulRequests']!=count:raise SystemExit(1)
